export function PreviewMode({
  pageTitle = "{{pageTitle}}",
  pageBody = "{{pageBody}}",
  device = "{{device}}",
  accent = "{{accent}}",
  isPublished = {{isPublished}},
}) {
  const mobile = device === "mobile";
  return (
    <div style={{ display: "flex", justifyContent: "center", fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 24 }}>
      <div style={{ background: "#fff", borderRadius: mobile ? 22 : 14, boxShadow: "0 14px 32px rgba(36,20,48,.18)", overflow: "hidden",
        width: mobile ? 220 : 360, border: mobile ? "6px solid #241430" : "none" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "10px 12px", background: "#24143008", borderBottom: "1px solid #24143014" }}>
          {!mobile && [0, 1, 2].map((i) => <span key={i} style={{ width: 8, height: 8, borderRadius: "50%", background: "#24143026" }} />)}
          <span style={{ marginLeft: "auto", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".03em", color: accent }}>
            {isPublished ? "Published" : "Draft preview"}
          </span>
        </div>
        <div style={{ padding: mobile ? "16px 14px" : "20px 18px" }}>
          <h1 style={{ margin: "0 0 8px", fontSize: mobile ? 16 : 20 }}>{pageTitle}</h1>
          <p style={{ margin: "0 0 14px", fontSize: 14, color: "#241430cc" }}>{pageBody}</p>
          <button type="button" style={{ border: "none", color: "#241430", background: accent, padding: "8px 16px", borderRadius: 8, fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Read more</button>
        </div>
      </div>
    </div>
  );
}
